/* V2 visibility, responsive spacing, and collision fixes */
.section .copy{opacity:0!important;visibility:hidden;pointer-events:none!important;transform:translateY(18px)}
.section.active .copy{opacity:1!important;visibility:visible;pointer-events:auto!important;transform:none}
.section[data-index="2"]{align-items:flex-start;justify-content:center;padding-top:7vh}
.section[data-index="2"] .copy{max-width:46vw;text-align:center}
.section[data-index="6"]{justify-content:flex-start}
.section[data-index="6"] .copy{max-width:42vw}
@media(max-width:760px){
 body{overflow-x:hidden}.section{min-height:112svh;padding:9svh 20px 30svh;align-items:flex-start}.section.right,.section.center{justify-content:flex-start;text-align:left}.section .copy{width:calc(100vw - 40px);max-width:none;background:linear-gradient(90deg,rgba(7,7,7,.88),rgba(7,7,7,.18));padding:14px 10px 14px 0}.hero{align-items:flex-end}.hero .copy{margin-bottom:9svh}.hero h1{font-size:clamp(64px,23vw,112px)}h2{font-size:clamp(44px,16vw,76px)}.body-copy{font-size:18px}.stats{grid-template-columns:1fr}
 #exploded-labels{inset:auto 12px calc(14px + env(safe-area-inset-bottom)) 12px;height:auto;display:flex;gap:8px;overflow-x:auto;align-items:stretch;padding:0 0 4px;scroll-snap-type:x proximity}.part-label,.part-label[data-id]{position:relative;inset:auto!important;flex:0 0 72vw;width:72vw;min-height:92px;scroll-snap-align:start;background:rgba(5,5,5,.92);font-size:10px}.part-label b{font-size:10px}#leader-svg{display:none!important}
 #finale-ui{left:12px;right:12px;bottom:calc(12px + env(safe-area-inset-bottom));width:auto;max-height:48svh;overflow:auto}.section[data-index="6"]{padding-bottom:57svh}.section[data-index="6"] .copy{max-width:none}.controls{grid-template-columns:1fr}.end-card{padding-bottom:24svh}#scroll-film{right:5px}
}
